CREATE TABLE novaworks.platform_organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES novaworks.users(id),created_at TEXT NOT NULL);
CREATE TABLE novaworks.platform_memberships(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),user_id TEXT NOT NULL REFERENCES novaworks.users(id),role TEXT NOT NULL CHECK(role IN ('OWNER','ADMIN','MANAGER','MEMBER')),created_at TEXT NOT NULL,PRIMARY KEY(organization_id,user_id));
CREATE TABLE novaworks.platform_projects(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),id TEXT NOT NULL,name TEXT NOT NULL,client_name TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',manager_id TEXT NOT NULL,deadline TEXT,status TEXT NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','ACTIVE','DONE','ARCHIVED')),created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,manager_id) REFERENCES novaworks.platform_memberships(organization_id,user_id));
CREATE TABLE novaworks.platform_tasks(organization_id TEXT NOT NULL,id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',assignee_id TEXT NOT NULL,deadline TEXT,estimated_hours DOUBLE PRECISION CHECK(estimated_hours>0),status TEXT NOT NULL DEFAULT 'TODO' CHECK(status IN ('TODO','IN_PROGRESS','DONE')),created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,project_id) REFERENCES novaworks.platform_projects(organization_id,id),FOREIGN KEY(organization_id,assignee_id) REFERENCES novaworks.platform_memberships(organization_id,user_id));
CREATE TABLE novaworks.platform_drafts(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),id TEXT NOT NULL,payload TEXT NOT NULL,created_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES novaworks.platform_memberships(organization_id,user_id));
CREATE TABLE novaworks.platform_files(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),id TEXT NOT NULL,name TEXT NOT NULL,storage_key TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id),UNIQUE(organization_id,storage_key),FOREIGN KEY(organization_id,created_by) REFERENCES novaworks.platform_memberships(organization_id,user_id));
CREATE TABLE novaworks.platform_invitations(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),id TEXT NOT NULL,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('ADMIN','MANAGER','MEMBER')),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,accepted_at TEXT,created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id));
CREATE TABLE novaworks.platform_audit(organization_id TEXT NOT NULL REFERENCES novaworks.platform_organizations(id),id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(organization_id,id));
CREATE INDEX platform_projects_manager ON novaworks.platform_projects(organization_id,manager_id);
CREATE INDEX platform_tasks_assignee ON novaworks.platform_tasks(organization_id,assignee_id);
